3	/// Clip ▸ Switch by Speaker… (road map "creator-jobs" SW2b, spec §11 SW-23 (g), SW-26 (a)): the
4	/// selected cameras and microphones of the container being edited — the timeline, or the open
5	/// nest — put up in `SwitchSpeakerSheetController`, whose Switch writes a Program track as one
6	/// undo step "Switch by Speaker". `switch_by_speaker` mirrors it (`AgentServer+Switch.swift`).
7	/// With one microphone and faces still to find, the Analyzing sheet comes first (SW8).
8	extension EditorViewController {
9	
10	    /// SW-23 (g) over the document's selection.
11	    private func switchSpeakerOffered(_ document: ProjectDocument) -> Bool {
12	        let snapshot = document.editedProject.snapshot
13	        let clips = document.selection.sorted().compactMap { snapshot.clip($0) }
14	        return SpeakerSwitch.canOffer(clips, in: snapshot)
15	    }
16	
17	    /// In the faces mode with faces missing (SW8, spec §11 SW-85), CJ-28's Analyzing sheet first,
18	    /// `EditorViewController+ShotSplit.swift`'s shape, and the switch sheet once they land.
19	    @objc func showSwitchBySpeakerSheet(_ sender: Any?) {
20	        guard let document, view.window?.attachedSheet == nil, switchSpeakerOffered(document)
21	        else {
22	            NSSound.beep()
23	            return
24	        }
25	        var wants: [SpeakerSwitch.FacesWant] = []
26	        if let input = SpeakerSwitch.read(
27	            from: document, clips: nil, pairing: nil, range: nil, settings: SpeakerSwitch.Settings())
28	        {
29	            do {
30	                wants = try SpeakerSwitch.facesWanted(input, in: document)
31	            } catch {
32	                refuseSwitchSpeaker(error.localizedDescription, document: document)
33	                return
34	            }
35	        }
36	        guard !wants.isEmpty else {
37	            presentAsSheet(SwitchSpeakerSheetController(document: document))
38	            return
39	        }
40	        let asked = document.project
41	        let scope = document.scope
42	        let rows = wants.map { AnalyzingSheetController.Row(name: $0.media.name, request: $0.request) }
43	        presentAsSheet(
44	            AnalyzingSheetController(
45	                document: document, command: SpeakerSwitch.actionName, rows: rows
46	            ) { [weak self, weak document] outcome in
47	                guard let self, let document else { return }
48	                guard document.project === asked, document.scope == scope else {
49	                    self.refuseSwitchSpeaker(
50	                        "the project changed while \(SpeakerSwitch.actionName) was analyzing, so "
51	                            + "nothing was switched. Choose \(SpeakerSwitch.actionName) again.",
52	                        document: document)
53	                    return
54	                }
55	                switch outcome {
56	                case .failed(let name, let why):
57	                    self.refuseSwitchSpeaker(
58	                        "The faces analysis of “\(name)” failed: \(why).", document: document)
59	                case .landed:
60	                    self.presentAsSheet(SwitchSpeakerSheetController(document: document))
61	                }
62	            })
63	    }
64	
65	    /// A beep and the sentence at the inspector's foot.
66	    private func refuseSwitchSpeaker(_ reason: String, document: ProjectDocument) {
67	        NSSound.beep()
68	        NotificationCenter.default.post(
69	            name: .projectDocumentDidRefuse, object: document,
70	            userInfo: ["refusal": ReelRefusal(op: "switch_by_speaker", reason: reason)])
71	    }
72	
73	    /// The menu arm, answered from `validateUserInterfaceItem`'s default case; nil for any
74	    /// other action. On when the selection holds two or more angles and a clip with sound
75	    /// (SW-23 (g)) and no sheet is on the window; allowed inside a nest.
76	    func validateSwitchSpeakerAction(_ action: Selector) -> Bool? {
77	        guard action == #selector(showSwitchBySpeakerSheet(_:)) else { return nil }
78	        guard let document, view.window?.attachedSheet == nil else { return false }
79	        return switchSpeakerOffered(document)
80	    }
81	}
